var a=`0030-korovai`;var i=`world-0030`;var t=`UA`;var o=`eastern-europe`;var r=12;var s=178;var g={en:`Korovai`,ua:`Коровай`};var u={en:`A classic dish from Ukraine, featuring whole cow milk, chicken egg, white bread. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: цільне коров'яче молоко, куряче яйце, білий хліб. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 90 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 90 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:90,i:[[`all-purpose-flour`,850,`g`],[`whole-cow-milk`,360,`ml`],[`instant-yeast`,13,`g`],[`white-granulated-sugar`,95,`g`],[`unsalted-butter`,120,`g`],[`chicken-egg`,4,`pcs`],[`table-salt`,8,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 40 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 40 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:40,i:[[`white-bread`,40,`g`]]},{en:`Bake in a preheated 180°C oven for about 45 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 45 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:45,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`honey`,35,`g`]]}];var d={slug:a,id:i,country:`UA`,region:o,servings:12,minutes:178,title:g,text:u,steps:l};export{t as country,d as default,i as id,s as minutes,o as region,r as servings,a as slug,l as steps,u as text,g as title};